-- All identities, reports and audit records below are rolled back.
BEGIN;
CREATE TEMP TABLE spending_test_actors(label text,uid uuid,sid uuid);
INSERT INTO spending_test_actors SELECT x,gen_random_uuid(),gen_random_uuid() FROM unnest(ARRAY['admin','staff','other','unassigned']) x;
INSERT INTO auth.users(id,aud,role,email) SELECT uid,'authenticated','authenticated','spending-test-'||uid||'@example.invalid' FROM spending_test_actors;
INSERT INTO auth.sessions(id,user_id,created_at,updated_at) SELECT sid,uid,now(),now() FROM spending_test_actors;
INSERT INTO hp_private.session_activity(session_id,user_id) SELECT sid,uid FROM spending_test_actors;
INSERT INTO public.hp_user_facilities(user_id,facility_code,role) SELECT uid,CASE WHEN label='other' THEN '06117' ELSE '06116' END,CASE WHEN label='admin' THEN 'ADMIN' ELSE 'STAFF' END FROM spending_test_actors WHERE label<>'unassigned';
CREATE TEMP TABLE spending_test_results(name text);
GRANT SELECT ON spending_test_actors TO authenticated;
GRANT ALL ON spending_test_results TO authenticated;
SET LOCAL ROLE anon;
DO $$BEGIN BEGIN PERFORM * FROM public.hp_spending_reports;RAISE EXCEPTION 'Anon can read';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END$$;
RESET ROLE;
INSERT INTO spending_test_results VALUES('anonymous cannot read');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims',(SELECT jsonb_build_object('sub',uid,'session_id',sid,'role','authenticated')::text FROM spending_test_actors WHERE label='staff'),true);
DO $$DECLARE p public.hp_spending_reports;n int;v jsonb;BEGIN
 IF (SELECT count(*) FROM public.hp_spending_reports WHERE period=0)<>1 THEN RAISE EXCEPTION 'Staff scope failed';END IF;
 SELECT * INTO STRICT p FROM public.hp_spending_reports WHERE facility_code='06116' AND period=0 AND fiscal_year=2570;
 v:=jsonb_build_object('amounts','{}'::jsonb,'note','','plan_id',p.id,'plan_revision',p.revision);
 INSERT INTO public.hp_spending_reports(facility_code,fiscal_year,period,status,payload) VALUES('06116',2570,10,'draft',v);
 IF EXISTS(SELECT 1 FROM public.hp_finance_monthly WHERE facility_code='06116' AND fiscal_year=2570 AND review_status='accepted') THEN RAISE EXCEPTION 'Draft was published';END IF; INSERT INTO spending_test_results VALUES('draft not published');
 BEGIN INSERT INTO public.hp_spending_reports(facility_code,fiscal_year,period,status,payload) VALUES('06117',2570,10,'draft',v);RAISE EXCEPTION 'Cross-unit insert accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE public.hp_spending_reports SET revision=revision+1 WHERE period=0;GET DIAGNOSTICS n=ROW_COUNT;IF n<>0 THEN RAISE EXCEPTION 'Staff modified source plan';END IF;
 INSERT INTO spending_test_results VALUES('cross-unit write and staff plan update blocked');
 BEGIN UPDATE public.hp_spending_reports SET status='confirmed',revision=2 WHERE facility_code='06116' AND period=10 AND fiscal_year=2570;RAISE EXCEPTION 'Incomplete confirmation accepted';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE public.hp_spending_reports SET payload=jsonb_set(payload,'{amounts}','{"forged":1}'),revision=2 WHERE period=10 AND fiscal_year=2570;RAISE EXCEPTION 'Unknown item accepted';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE public.hp_spending_reports SET revision=1 WHERE period=10 AND fiscal_year=2570;RAISE EXCEPTION 'Stale revision accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
 INSERT INTO spending_test_results VALUES('incomplete report, unknown item and stale revision rejected');
 SELECT jsonb_object_agg(r->>'id',0) INTO v FROM jsonb_array_elements(p.payload->'groups') g CROSS JOIN LATERAL jsonb_array_elements(g->'rows') r WHERE r->>'input'='true';
 UPDATE public.hp_spending_reports SET payload=jsonb_set(payload,'{amounts}',v),status='confirmed',revision=2 WHERE period=10 AND fiscal_year=2570;
 IF (SELECT count(*) FROM public.hp_finance_monthly WHERE facility_code='06116' AND fiscal_year=2570 AND review_status='accepted' AND amount=0)<>1 THEN RAISE EXCEPTION 'Confirmed zero total missing';END IF; BEGIN UPDATE public.hp_finance_monthly SET amount=999 WHERE facility_code='06116' AND fiscal_year=2570;RAISE EXCEPTION 'Manual aggregate edit accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END; INSERT INTO spending_test_results VALUES('confirmed zero publishes; manual aggregate edit blocked'); BEGIN UPDATE public.hp_spending_reports SET status='draft',reason='test',revision=3 WHERE period=10 AND fiscal_year=2570;RAISE EXCEPTION 'Staff reopened confirmed month';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN DELETE FROM public.hp_spending_reports WHERE period=10;RAISE EXCEPTION 'Hard delete accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 INSERT INTO spending_test_results VALUES('complete zero report confirms; staff reopen and hard-delete blocked');
END$$;
SELECT set_config('request.jwt.claims',(SELECT jsonb_build_object('sub',uid,'session_id',sid,'role','authenticated')::text FROM spending_test_actors WHERE label='other'),true);
DO $$BEGIN IF EXISTS(SELECT 1 FROM public.hp_spending_reports WHERE facility_code='06116') THEN RAISE EXCEPTION 'Other staff reads data';END IF;INSERT INTO spending_test_results VALUES('other unit cannot read report');END$$;
SELECT set_config('request.jwt.claims',(SELECT jsonb_build_object('sub',uid,'session_id',sid,'role','authenticated')::text FROM spending_test_actors WHERE label='unassigned'),true);
DO $$BEGIN IF EXISTS(SELECT 1 FROM public.hp_spending_reports) THEN RAISE EXCEPTION 'Unassigned reads data';END IF;INSERT INTO spending_test_results VALUES('unassigned authenticated cannot read');END$$;
SELECT set_config('request.jwt.claims',(SELECT jsonb_build_object('sub',uid,'session_id',sid,'role','authenticated')::text FROM spending_test_actors WHERE label='admin'),true);
DO $$DECLARE n int;BEGIN
 IF (SELECT count(*) FROM public.hp_spending_reports WHERE period=0)<>8 THEN RAISE EXCEPTION 'Admin plans missing';END IF;
 UPDATE public.hp_spending_reports SET status='draft',reason='ทดสอบเปิดเดือน',revision=3 WHERE facility_code='06116' AND fiscal_year=2570 AND period=10;
 GET DIAGNOSTICS n=ROW_COUNT;IF n<>1 THEN RAISE EXCEPTION 'Admin reopen failed';END IF;
 UPDATE public.hp_spending_reports SET status='deleted',reason='ทดสอบลบแบบกู้คืน',revision=4 WHERE facility_code='06116' AND fiscal_year=2570 AND period=10;
 UPDATE public.hp_spending_reports SET status='draft',revision=5 WHERE facility_code='06116' AND fiscal_year=2570 AND period=10;
 IF EXISTS(SELECT 1 FROM public.hp_finance_monthly WHERE facility_code='06116' AND fiscal_year=2570 AND review_status='accepted') THEN RAISE EXCEPTION 'Reopened report still published';END IF; UPDATE public.hp_spending_reports SET payload=jsonb_set(payload,ARRAY['amounts',(SELECT key FROM jsonb_each(payload->'amounts') LIMIT 1)],'123.45'::jsonb),status='confirmed',revision=6 WHERE facility_code='06116' AND fiscal_year=2570 AND period=10; IF (SELECT count(*) FROM public.hp_finance_monthly WHERE facility_code='06116' AND fiscal_year=2570 AND amount=123.45 AND review_status='accepted')<>1 THEN RAISE EXCEPTION 'Reconfirmation duplicated or wrong total';END IF; INSERT INTO spending_test_results VALUES('reopen withdraws total; reconfirm updates same monthly aggregate');
END$$;
RESET ROLE;
DO $$BEGIN IF NOT EXISTS(SELECT 1 FROM public.hp_audit_logs a JOIN spending_test_actors t ON t.uid=a.user_id WHERE a.table_name='hp_spending_reports' AND a.operation='UPDATE') THEN RAISE EXCEPTION 'Audit missing';END IF;END$$;
INSERT INTO spending_test_results VALUES('audit trail recorded');
SELECT jsonb_agg(name) AS passed FROM spending_test_results;
ROLLBACK;
